mapper.select:
SELECT PRODUCT_COMM_ID, PRODUCT_ID,USER_ID,CONTENT,ELIKE,reip,bcdate,USER_NAME, row_num FROM (
SELECT PRODUCT_COMM_ID, PRODUCT_ID,USER_ID,CONTENT,ELIKE,reip,bcdate,USER_NAME, ROW_NUMBER()
OVER(ORDER BY PRODUCT_COMM_ID desc) AS row_num FROM PRODUCT_COMM where PRODUCT_ID=#{prodid}
) WHERE row_num BETWEEN #{begin} AND #{end}
